window.QSIMPLE={"themes":{"guide":"Métier de CI","ssuap":"Bilans & SSUAP","acr":"ACR · DAE · chaleur","efibi":"eFiBi & procédures","bsp":"Règlements BSPP"},"items":[{"id":"s:guide:0","g":"guide","k":"qcm","q":"À quoi sert le « Guide pratique CI en réseau BSPP » ?","answer":2,"explication":"C'est le référentiel qui accompagne les Chefs d'Intervention CRf en garde dans les casernes de la BSPP, et le programme de leur formation initiale.","ref":{"d":"guide","p":1},"choices":["À recruter des sapeurs-pompiers","À apprendre le secourisme de base","À aider les CI Croix-Rouge en mission dans les centres de secours BSPP"]},{"id":"s:guide:1","g":"guide","k":"vf","q":"Le guide pratique CI BSPP est notamment inspiré du référentiel BSP 118.1.","answer":true,"explication":"Oui ! Le guide s'appuie sur le BSP 118.1 et t'invite même à rédiger ton propre aide-mémoire à partir de lui.","ref":{"d":"guide","p":1}},{"id":"s:guide:2","g":"guide","k":"qcm","q":"En combien de Groupements d'Incendie et de Secours (GIS) sont répartis les centres de secours BSPP ?","answer":0,"explication":"Les 71 centres de secours de la BSPP sont répartis en 3 GIS, eux-mêmes divisés en compagnies.","ref":{"d":"guide","p":4},"choices":["3","5","12"]},{"id":"s:guide:3","g":"guide","k":"qcm","q":"Dans l'indicatif radio « Croix-Rouge française 0101 » à Chaligny, que veut dire le premier « 01 » ?","answer":1,"explication":"01 = 1re compagnie, puis 0 pour le PC de compagnie et 1 pour le premier engin CRf du CS. À la radio, on dit simplement « 101 ».","ref":{"d":"guide","p":4},"choices":["Le premier jour de garde","La première compagnie","Le premier arrondissement"]},{"id":"s:guide:4","g":"guide","k":"qcm","q":"Combien de temps avant le début de la vacation l'équipage doit-il se présenter au centre de secours ?","answer":0,"explication":"Arriver au moins 15 minutes avant permet d'être vraiment opérationnel à l'heure. La ponctualité, c'est déjà du secourisme !","ref":{"d":"guide","p":5},"choices":["Au moins 15 minutes avant","Pile à l'heure","5 minutes après, le temps de se garer"]},{"id":"s:guide:5","g":"guide","k":"vf","q":"Au centre de secours, on tutoie les pompiers pour créer une ambiance détendue.","answer":false,"explication":"Au contraire : on dit bonjour à chacun et on vouvoie ses interlocuteurs. Le CS est une enceinte militaire où l'équipage CRf est invité.","ref":{"d":"guide","p":5}},{"id":"s:guide:6","g":"guide","k":"qcm","q":"Au CS, qui est ton premier contact, prend les rentrées et fait sonner l'équipage pour les interventions ?","answer":2,"explication":"Le stationnaire, installé au PVO, est ton premier contact au téléphone comme en vrai. C'est lui qui déclenche ton départ.","ref":{"d":"guide","p":5},"choices":["Le garde remise","Le chef de garde","Le stationnaire"]},{"id":"s:guide:7","g":"guide","k":"qcm","q":"Que signifie le sigle PVO ?","answer":0,"explication":"Le PVO (Poste de Veille Opérationnelle) est le cœur du CS : c'est là que se trouve le stationnaire et que tu récupères l'ordre de départ.","ref":{"d":"guide","p":58},"choices":["Poste de Veille Opérationnelle","Point de Vérification de l'Oxygène","Plan de Voirie Officiel"]},{"id":"s:guide:8","g":"guide","k":"qcm","q":"Qui est le référent matériel du CS, celui qui te fait percevoir la bouteille d'oxygène ?","answer":2,"explication":"Le garde remise gère le matériel du CS. Pour le solliciter, tu passes par le stationnaire.","ref":{"d":"guide","p":5},"choices":["Le sergent de jour","L'officier de garde compagnie","Le garde remise"]},{"id":"s:guide:9","g":"guide","k":"qcm","q":"Tu as un doute sur un rapport ou une procédure : quel est ton référent technique au CS ?","answer":0,"explication":"Le sergent de jour est ton contact privilégié en cas de doute ; tu le joins via le PVO. S'il est indisponible, le PVO bascule vers le chef de garde.","ref":{"d":"guide","p":5},"choices":["Le sergent de jour","Le chef de garde","Le conducteur du VSAV"]},{"id":"s:guide:10","g":"guide","k":"vf","q":"Le chef de garde établit le planning journalier de la garde incendie du jour.","answer":true,"explication":"Exact : il établit le planning de la garde, en contrôle la conformité et garantit la couverture opérationnelle du secteur.","ref":{"d":"guide","p":5}},{"id":"s:guide:11","g":"guide","k":"qcm","q":"Qui est l'« Onyx » ?","answer":1,"explication":"L'Onyx est le cadre de permanence CRf : il soutient les équipages en garde BSPP, pour tout conseil que tu préfères demander en interne.","ref":{"d":"guide","p":8},"choices":["Le centre opérationnel de la BSPP","Le cadre de permanence territorial de la Croix-Rouge","Le chef de garde du CS"]},{"id":"s:guide:12","g":"guide","k":"vf","q":"En cas d'arrêt cardiaque, tu préviens d'abord l'Onyx, puis tu demandes l'équipe médicale.","answer":false,"explication":"Non : les demandes de moyens vont d'abord à la BSPP. On demande l'équipe médicale et les renforts, puis on prévient l'Onyx.","ref":{"d":"guide","p":8}},{"id":"s:guide:13","g":"guide","k":"qcm","q":"Quel signal du ronfleur annonce un départ pour l'équipage Croix-Rouge ?","answer":1,"explication":"Courte - longue - courte : c'est le signal CRf sur tout le secteur BSPP. Pense à le vérifier avec le PVO en début de vacation.","ref":{"d":"guide","p":17},"choices":["3 sonneries longues","1 courte, 1 longue, 1 courte","1 seule sonnerie courte"]},{"id":"s:guide:14","g":"guide","k":"vf","q":"Au ronfleur, l'équipage peut emprunter la perche de feu pour gagner du temps.","answer":false,"explication":"Interdiction absolue, il y a eu des accidents. On rejoint le VPSP sans courir : laisse la perche aux pompiers !","ref":{"d":"guide","p":17}},{"id":"s:guide:15","g":"guide","k":"qcm","q":"Au ronfleur, où se rend le Chef d'Intervention ?","answer":1,"explication":"Le CI passe au PVO récupérer l'ordre de départ, la radio BSPP, la tablette et les infos du stationnaire ; le reste de l'équipage file au VPSP.","ref":{"d":"guide","p":17},"choices":["Directement au volant du VPSP","Au PVO, chercher l'ordre de départ, la radio et la tablette","Au bureau du chef de garde"]},{"id":"s:guide:16","g":"guide","k":"qcm","q":"Sur l'ordre de départ, que signifie une « procédure rouge » ?","answer":2,"explication":"Rouge = détresse vitale évidente : la coordination est avertie d'emblée et décide d'envoyer ou non une équipe médicale.","ref":{"d":"guide","p":18},"choices":["Une intervention annulée","Une adresse introuvable","Une détresse vitale évidente"]},{"id":"s:guide:17","g":"guide","k":"qcm","q":"Dans quel délai la BSPP s'engage-t-elle à être présentée sur les lieux après le décroché de l'appel ?","answer":1,"explication":"L'engagement est de 10 minutes. Mais la sécurité de l'équipage et des usagers de la route reste la priorité absolue.","ref":{"d":"guide","p":19},"choices":["5 minutes","10 minutes","30 minutes"]},{"id":"s:guide:18","g":"guide","k":"vf","q":"Le chauffeur peut refuser une consigne du CI qui irait contre le code de la route.","answer":true,"explication":"Oui : le chauffeur est maître du véhicule et engage son permis. Le CI, lui, peut interdire toute conduite dangereuse pour l'équipage.","ref":{"d":"guide","p":19}},{"id":"s:guide:19","g":"guide","k":"qcm","q":"Tu es bloqué dans la circulation en route vers l'intervention : que demandes-tu au Golf ?","answer":0,"explication":"Tu demandes « faites partir un autre engin » en signalant ton blocage. Attention, ta mission continue : tu dois quand même t'y rendre !","ref":{"d":"guide","p":20},"choices":["De faire partir un autre engin","D'annuler l'intervention","De t'envoyer une escorte de police"]},{"id":"s:guide:20","g":"guide","k":"qcm","q":"Qui est ton interlocuteur principal en phonie pendant une intervention ?","answer":0,"explication":"Le CSO (« Golf ») est ton interlocuteur radio. En cas de souci radio, tu l'appelles par téléphone, et en dernier recours le PVO.","ref":{"d":"guide","p":9},"choices":["Le CSO, appelé « Golf »","Le SAMU","L'Onyx"]},{"id":"s:guide:21","g":"guide","k":"qcm","q":"La demande de moyens suit le mnémotechnique SAM. Que veut dire SAM ?","answer":1,"explication":"SAM : Service - Adresse - Motif. Exemple : « Je demande tel moyen, telle adresse, tel motif ». Simple comme bonjour.","ref":{"d":"guide","p":10},"choices":["Secours - Alerte - Message","Service - Adresse - Motif","Sécurité - Accès - Matériel"]},{"id":"s:guide:22","g":"guide","k":"qcm","q":"Tu commences un message radio devenu inutile : quelle phrase utilises-tu pour l'interrompre ?","answer":2,"explication":"« Golf (X), annulez la transmission » interrompt proprement le message. Pour une erreur, tu dis « Correction, lire... ».","ref":{"d":"guide","p":15},"choices":["« Golf, oubliez tout »","« Golf, terminé »","« Golf, annulez la transmission »"]},{"id":"s:guide:23","g":"guide","k":"vf","q":"Le bouton rouge de la radio BSPP est à utiliser quand l'équipage est en danger.","answer":false,"explication":"Contrairement aux apparences, ce bouton rouge (en haut à droite du portatif) n'est pas utilisé dans les procédures actuelles en cas de danger pour l'équipage.","ref":{"d":"guide","p":16}},{"id":"s:guide:24","g":"guide","k":"qcm","q":"Sur la radio ANTARES, que signifie le statut 7 ?","answer":0,"explication":"Statut 7 = Disponible. Le 9 = Rentré et le 5 = Transport hôpital. Ces statuts remplacent la plupart des messages en phonie.","ref":{"d":"guide","p":49},"choices":["Disponible","Rentré","Transport hôpital"]},{"id":"s:guide:25","g":"guide","k":"qcm","q":"Sur la radio ANTARES, quel statut indique « Parti » en intervention ?","answer":2,"explication":"Statut 1 = Parti, puis statut 2 = Sur les lieux. Le départ en statut, c'est le réflexe dès que tu roules.","ref":{"d":"guide","p":49},"choices":["Statut 9","Statut 2","Statut 1"]},{"id":"s:guide:26","g":"guide","k":"vf","q":"En sortant de l'hôpital, il faut toujours passer le statut 25 puis le statut 7.","answer":true,"explication":"Oui : 25 « Quitte l'hôpital », puis 7 « Disponible », tout de suite si l'hôpital est sur ton secteur, ou une fois revenu sur celui-ci sinon.","ref":{"d":"guide","p":10}},{"id":"s:guide:27","g":"guide","k":"qcm","q":"Combien d'accompagnants peux-tu prendre au maximum lors d'une évacuation ?","answer":1,"explication":"Un accompagnant au maximum, majeur, assis et ceinturé. Le VPSP n'est pas un bus, même avec la meilleure volonté !","ref":{"d":"guide","p":34},"choices":["Aucun","Un seul, obligatoirement majeur","Deux, si ce sont des proches"]},{"id":"s:guide:28","g":"guide","k":"vf","q":"L'évacuation vers l'hôpital se fait toujours avec les avertisseurs sonores.","answer":false,"explication":"Non : les avertisseurs sonores ne sont utilisés en évacuation que sur demande de la coordination médicale.","ref":{"d":"guide","p":34}},{"id":"s:guide:29","g":"guide","k":"qcm","q":"À l'hôpital, qui signe la transmission du patient sur la tablette eFibi ?","answer":1,"explication":"Tu cliques sur « Transmission du patient » dans eFibi et tu fais signer l'IAO (infirmier d'accueil) sur la tablette.","ref":{"d":"guide","p":34},"choices":["Le conducteur du VPSP","L'IAO de l'hôpital","La victime"]},{"id":"s:guide:30","g":"guide","k":"qcm","q":"À qui communiques-tu le message de rentrée ?","answer":0,"explication":"Le message de rentrée se donne au PVO dès le retour, après avoir remis la radio en charge.","ref":{"d":"guide","p":35},"choices":["Au PVO, dès le retour d'intervention","Au SAMU par téléphone","À l'Onyx par SMS"]},{"id":"s:guide:31","g":"guide","k":"qcm","q":"Combien de points comporte au total le message de rentrée ?","answer":2,"explication":"Neuf points au total, mais pour un moyen associatif ce sont surtout les points 1 et 5 qui sont systématiques (et le 2 s'il y a une victime).","ref":{"d":"guide","p":35},"choices":["Trois","Cinq","Neuf"]},{"id":"s:guide:32","g":"guide","k":"vf","q":"Au point 5 du message de rentrée, si les secours n'ont rien abîmé, on dit « néant ».","answer":true,"explication":"Exact : le point 5 décrit les dégâts causés par les secours (vêtement découpé, vitre cassée...). Si rien : « néant ».","ref":{"d":"guide","p":35}},{"id":"s:guide:33","g":"guide","k":"qcm","q":"Par quoi se termine le message de rentrée ?","answer":1,"explication":"On termine par le CRI, qui code le type d'intervention. La liste complète est disponible au PVO.","ref":{"d":"guide","p":36},"choices":["Par le numéro de la radio","Par un CRI (Code Retour Intervention)","Par le nom de l'hôpital"]},{"id":"s:guide:34","g":"guide","k":"qcm","q":"Parmi les CRI les plus courants, à quoi correspond le code 320 ?","answer":2,"explication":"320 = Maladie (affection médicale). 310 = Intoxication et 356 = Chute. Tu le placeras souvent, celui-là !","ref":{"d":"guide","p":36},"choices":["Chute","Intoxication","Maladie"]},{"id":"s:guide:35","g":"guide","k":"qcm","q":"Comment s'appelle l'application de fiche bilan utilisée sur la tablette ?","answer":2,"explication":"La fiche bilan se rédige désormais sur tablette via eFibi. ADAGIO, c'est le rapport d'intervention, et ANTARES, le réseau radio.","ref":{"d":"guide","p":32},"choices":["ADAGIO","ANTARES","eFibi"]},{"id":"s:guide:36","g":"guide","k":"vf","q":"La fiche bilan papier ne s'utilise qu'en cas de défaillance d'eFibi.","answer":true,"explication":"Oui, uniquement dans ce cas. Le bilan doit ensuite être régularisé sur eFibi avec une photo de la fiche papier.","ref":{"d":"guide","p":32}},{"id":"s:guide:37","g":"guide","k":"vf","q":"Utiliser le DSA fait partie des cas où le déplacement de l'Onyx est obligatoire.","answer":true,"explication":"Exact : l'utilisation du DSA déclenche obligatoirement le déplacement de l'Onyx, comme un accident de la route impliquant la CRf.","ref":{"d":"guide","p":47}},{"id":"s:guide:38","g":"guide","k":"qcm","q":"Que dit le guide à propos des « groupes » BSPP présentés en annexe ?","answer":2,"explication":"Un groupe rassemble des engins pour une problématique précise. On ne te demande pas de les connaître, mais ça aide en situation exceptionnelle.","ref":{"d":"guide","p":48},"choices":["Le CI doit tous les connaître par cœur","Ils ne concernent que les incendies","Ce sont des ensembles standardisés d'engins ; les connaître est un plus"]},{"id":"s:guide:39","g":"guide","k":"qcm","q":"En fin de garde, que dois-tu restituer au centre de secours ?","answer":0,"explication":"Bouteille d'O2 prêtée, radio et tablette retournent au CS. Et on vérifie que tous les rapports du jour sont bien validés !","ref":{"d":"guide","p":39},"choices":["La bouteille d'oxygène prêtée, la radio et la tablette","Les chasubles de l'équipage","Les clés du VPSP"]},{"id":"s:guide:40","g":"guide","k":"qcm","q":"Que présente le document « Groupes et renforts BSPP » ?","answer":0,"explication":"Ce document liste, sous forme de tableaux, la composition des groupes et renforts d'engins que la BSPP peut engager.","ref":{"d":"groupes","p":1},"choices":["Des tableaux des groupes et renforts d'engins de la BSPP","Les horaires des gardes CRf","La liste des hôpitaux parisiens"]},{"id":"s:guide:41","g":"guide","k":"vf","q":"Dans « Groupes », le groupe Ventilation (G.VEN) comprend un ventilateur maître (VM).","answer":true,"explication":"Oui : le G.VEN réunit un VM (Ventilateur Maître) et un VAR (Ventilateur Auxiliaire Relais). Ça souffle fort chez les pompiers !","ref":{"d":"groupes","p":7}},{"id":"s:guide:42","g":"guide","k":"qcm","q":"Dans « Groupes », que signifie le sigle GST ?","answer":1,"explication":"Le GST est le Groupe Soutien Télécommunications ; un deuxième GST peut même être mis en service par plan de rappel.","ref":{"d":"groupes","p":6},"choices":["Groupe de Secours Terrestre","Groupe Soutien Télécommunications","Groupe Sanitaire Temporaire"]},{"id":"s:guide:43","g":"guide","k":"qcm","q":"Dans « Groupes », quelle situation figure dans la rubrique « Milieu souterrain » ?","answer":1,"explication":"La rubrique Milieu souterrain prévoit notamment l'effondrement (CMA 710), la personne ensevelie ou le feu ou explosion en sous-sol.","ref":{"d":"groupes","p":5},"choices":["Un feu de broussailles","Un effondrement","Des violences urbaines"]},{"id":"s:ssuap:0","g":"ssuap","k":"qcm","q":"À quoi sert le bilan primaire ?","answer":0,"explication":"Le bilan primaire traque la détresse vitale à traiter tout de suite. C'est un zoom sur la victime, pas sur la paperasse.","ref":{"d":"bilan","p":1},"choices":["Rechercher une détresse vitale qui menace immédiatement la vie","Remplir la partie administrative de la fiche bilan","Choisir l'hôpital de destination"]},{"id":"s:ssuap:1","g":"ssuap","k":"qcm","q":"Combien d'étapes compte le bilan primaire ?","answer":1,"explication":"Quatre étapes : sauvegarde immédiate, conscience, respiration, circulation. Facile à retenir, comme un bon refrain.","ref":{"d":"bilan","p":1},"choices":["Deux","Quatre","Six"]},{"id":"s:ssuap:2","g":"ssuap","k":"qcm","q":"En combien de temps environ doit-on savoir si l'état de la victime est critique ?","answer":2,"explication":"En une dizaine de secondes, on doit savoir si l'état est critique ou non. Rapide, mais ordonné et rigoureux !","ref":{"d":"bilan","p":1},"choices":["Dix minutes","Deux minutes","Une dizaine de secondes"]},{"id":"s:ssuap:3","g":"ssuap","k":"vf","q":"Face à une victime inconsciente, on recherche la respiration sur 10 secondes au maximum.","answer":true,"explication":"Oui : respiration et pouls carotidien se recherchent simultanément, sur 10 secondes au maximum.","ref":{"d":"bilan","p":2}},{"id":"s:ssuap:4","g":"ssuap","k":"qcm","q":"Une victime consciente présente une détresse respiratoire. Quelle position privilégier ?","answer":0,"explication":"La victime en détresse respiratoire est mise en position assise si c'est possible (pas de suspicion de fracture du bassin ou du rachis).","ref":{"d":"bilan","p":3},"choices":["Position assise","Allongée sur le dos","Jambes surélevées"]},{"id":"s:ssuap:5","g":"ssuap","k":"qcm","q":"Que veut dire le sigle UA ?","answer":1,"explication":"UA = Urgence Absolue : risque vital ou fonctionnel immédiat. Son cousin plus calme, c'est l'UR, Urgence Relative.","ref":{"d":"victime","p":1},"choices":["Unité d'Assistance","Urgence Absolue","Urgence Ambulancière"]},{"id":"s:ssuap:6","g":"ssuap","k":"vf","q":"Une parturiente, c'est-à-dire une femme qui accouche, est considérée comme une victime.","answer":true,"explication":"Oui, la parturiente fait partie des victimes au sens du BSP 200.2, même si accoucher n'est pas une maladie !","ref":{"d":"victime","p":1}},{"id":"s:ssuap:7","g":"ssuap","k":"qcm","q":"Comment appelle-t-on une personne sans dommage apparent mais directement liée à l'événement ?","answer":2,"explication":"L'impliqué n'a pas de dommage apparent mais est lié à l'événement par sa proximité avec les victimes. Il peut devenir victime ensuite.","ref":{"d":"victime","p":1},"choices":["Un témoin passif","Une victime UR","Un impliqué"]},{"id":"s:ssuap:8","g":"ssuap","k":"vf","q":"Une personne qui a bénéficié de la pose d'un garrot reste une UR si elle est transportée par un engin non médicalisé.","answer":false,"explication":"Faux : la pose d'un garrot fait d'elle une UA, même transportée par un engin non médicalisé. Ce sont les soins qui comptent.","ref":{"d":"victime","p":2}},{"id":"s:ssuap:9","g":"ssuap","k":"qcm","q":"Lequel de ces signes permet aux sapeurs-pompiers d'affirmer un décès certain ?","answer":0,"explication":"Les trois cas de décès certain : décapitation, putréfaction et raideur cadavérique. Le reste ne suffit pas.","ref":{"d":"deces","p":1},"choices":["La putréfaction","Une peau froide","Des pupilles dilatées"]},{"id":"s:ssuap:10","g":"ssuap","k":"vf","q":"En dehors des cas de décès certain, le constat de la mort revient exclusivement à un médecin.","answer":true,"explication":"Exact. Les secouristes poursuivent la réanimation jusqu'au constat de la mort par un médecin ou sur demande du médecin coordinateur.","ref":{"d":"deces","p":1}},{"id":"s:ssuap:11","g":"ssuap","k":"qcm","q":"En cas de mort suspecte, qui prévient la famille absente du défunt ?","answer":1,"explication":"Ce sont les forces de l'ordre qui préviennent la famille si elle n'est pas sur place. Toi, tu préserves les indices.","ref":{"d":"deces","p":1},"choices":["Le chef d'agrès","Les forces de l'ordre","Le voisin le plus proche"]},{"id":"s:ssuap:12","g":"ssuap","k":"qcm","q":"Dans les cas de non contact, laquelle de ces situations figure dans la liste ?","answer":2,"explication":"L'ivresse simple (marche possible, sans trouble neurologique ni traumatisme) fait partie des cas de non contact, sous conditions.","ref":{"d":"noncontact","p":1},"choices":["Une douleur thoracique typique","Une détresse respiratoire","Une ivresse simple avec marche possible"]},{"id":"s:ssuap:13","g":"ssuap","k":"vf","q":"Le Xarelto figure dans la liste des anticoagulants jointe aux cas de non contact.","answer":true,"explication":"Oui, le Xarelto (rivaroxaban) est dans la liste. Un anticoagulant peut empêcher certains cas de non contact, d'où l'intérêt de vérifier.","ref":{"d":"noncontact","p":2}},{"id":"s:ssuap:14","g":"ssuap","k":"qcm","q":"Selon la fiche CRf des cas de non contact, que faire en cas de doute ?","answer":0,"explication":"La fiche le dit avec humour : « Si vous avez un doute, pas de doute : contactez ! » Le médecin est là pour t'aider.","ref":{"d":"noncontact2","p":1},"choices":["Contacter la coordination médicale","Ne pas contacter pour gagner du temps","Attendre la fin du transport"]},{"id":"s:ssuap:15","g":"ssuap","k":"vf","q":"Pour un traumatisme simple en cas de non contact, la douleur doit être inférieure à 7/10.","answer":true,"explication":"Oui : douleur < 7/10 (ou EVS < 4), cinétique faible, pas de déficit vasculo-nerveux... toutes les conditions doivent être réunies.","ref":{"d":"noncontact2","p":2}},{"id":"s:ssuap:16","g":"ssuap","k":"qcm","q":"Le cas 13 autorise à transporter en interrompant l'appel après une attente téléphonique de plus de…","answer":1,"explication":"Après 10 minutes d'attente sur le numéro non urgent, et sous conditions (pas de douleur thoracique ni trouble respiratoire...).","ref":{"d":"noncontact2","p":3},"choices":["2 minutes","10 minutes","5 minutes"]},{"id":"s:ssuap:17","g":"ssuap","k":"qcm","q":"En hypothermie, combien de chocs électriques externes (CEE) sont désormais administrables ?","answer":2,"explication":"La mise à jour 2025 du BSP 200.2 (chapitres 7 et 12.1) passe de 1 à 3 CEE administrables en cas d'hypothermie. Une petite ligne qui compte !","ref":{"d":"maj2025","p":1},"choices":["1","5","3"]},{"id":"s:ssuap:18","g":"ssuap","k":"vf","q":"Les mises à jour du BSP 200.2 de 2025 pouvaient faire l'objet de contrôles opérationnels à partir du 1er mai 2025.","answer":true,"explication":"Oui : applicables dès prise de connaissance, contrôlables à compter du 1er mai 2025. De quoi réviser au printemps.","ref":{"d":"maj2025","p":1}},{"id":"s:ssuap:19","g":"ssuap","k":"qcm","q":"Que signifie le sigle AASC ?","answer":0,"explication":"AASC = Association Agréée de Sécurité Civile, comme la Croix-Rouge française. Te voilà dans le lexique !","ref":{"d":"maj2024","p":6},"choices":["Association Agréée de Sécurité Civile","Agent d'Accueil des Secours Civils","Assistance Ambulancière Sanitaire Coordonnée"]},{"id":"s:ssuap:20","g":"ssuap","k":"qcm","q":"Que signifie le sigle VSAV ?","answer":1,"explication":"Le VSAV, c'est le véhicule de Secours et d'Assistance aux Victimes, l'outil de travail principal en SSUAP.","ref":{"d":"maj2024","p":7},"choices":["Véhicule de Soins Avancés et de Ventilation","Véhicule de Secours et d'Assistance aux Victimes","Voiture de Sécurité d'Aide Vitale"]},{"id":"s:ssuap:21","g":"ssuap","k":"qcm","q":"Qui demande une escorte motorisée sur intervention, et auprès de qui ?","answer":2,"explication":"Depuis la mise à jour 2024, c'est le COS qui la demande au CSO TC : « je demande une escorte motorisée… ».","ref":{"d":"maj2024","p":1},"choices":["Le conducteur, auprès du SAMU","La victime, auprès de la police","Le COS, auprès du CSO TC"]},{"id":"s:ssuap:22","g":"ssuap","k":"vf","q":"Selon la FT 14.1, deux mouvements respiratoires ou plus sur 10 secondes signifient qu'il ne s'agit pas d'un arrêt respiratoire.","answer":true,"explication":"Exact. Aucun mouvement : arrêt respiratoire. Un seul : on réévalue sur 10 secondes maximum. Deux ou plus : pas d'arrêt.","ref":{"d":"maj2024","p":4}},{"id":"s:ssuap:23","g":"ssuap","k":"qcm","q":"Quelle est la maladie génétique la plus fréquente en Île-de-France ?","answer":0,"explication":"C'est la drépanocytose, qui modifie l'hémoglobine. Les flux migratoires expliquent sa fréquence en métropole.","ref":{"d":"drepano","p":1},"choices":["La drépanocytose","La mucoviscidose","L'hémophilie"]},{"id":"s:ssuap:24","g":"ssuap","k":"qcm","q":"Dans la drépanocytose, quelle forme prennent les globules rouges déformés ?","answer":1,"explication":"Une faucille, surtout quand ils manquent d'O2. Trop gros, ils bouchent les petits vaisseaux (capillaires).","ref":{"d":"drepano","p":1},"choices":["Une étoile","Une faucille","Un cube"]},{"id":"s:ssuap:25","g":"ssuap","k":"vf","q":"Chez une victime drépanocytaire qui a froid, il faut la réchauffer.","answer":true,"explication":"Oui : le froid favorise les crises (vasoconstriction). La conduite à tenir prévoit de réchauffer la victime si elle a froid.","ref":{"d":"drepano","p":1}},{"id":"s:ssuap:26","g":"ssuap","k":"qcm","q":"Sous quel format l'ambulance privée récupère-t-elle la fiche bilan dématérialisée ?","answer":2,"explication":"La fiche bilan est téléchargée au format PDF, après un contact avec la coordination médicale de la BSPP.","ref":{"d":"ambu","p":1},"choices":["Une photo du VSAV","Un fax papier","Un fichier PDF"]},{"id":"s:ssuap:27","g":"ssuap","k":"qcm","q":"D'après l'information patient, dans quel délai l'ambulance se présente-t-elle le plus souvent ?","answer":0,"explication":"Le plus souvent dans un délai n'excédant pas 45 minutes. Un peu de patience, mais pas trop.","ref":{"d":"ambu","p":2},"choices":["45 minutes au plus","15 minutes au plus","3 heures au plus"]},{"id":"s:ssuap:28","g":"ssuap","k":"qcm","q":"Quel est le premier maillon de la chaîne des secours ?","answer":1,"explication":"La sécurité vient en premier : éviter le suraccident et de nouvelles victimes. Un secouriste blessé ne sauve personne.","ref":{"d":"b2002","p":33},"choices":["L'alerte","La sécurité","La prise en charge hospitalière"]},{"id":"s:ssuap:29","g":"ssuap","k":"qcm","q":"Comment le BSP 200.2 décrit-il le bilan circonstanciel ?","answer":2,"explication":"Le bilan circonstanciel, c'est la photo panoramique de la scène, réalisée en quelques secondes. Le bilan primaire, lui, zoome sur la victime.","ref":{"d":"b2002","p":139},"choices":["Un interrogatoire sur les antécédents","Un examen de la tête aux pieds","Une photo panoramique de la situation"]},{"id":"s:ssuap:30","g":"ssuap","k":"qcm","q":"Face à une hémorragie externe sans corps étranger, quel est le premier geste ?","answer":0,"explication":"On réalise immédiatement une compression directe. En zone garrotable, le garrot vient si la compression directe ou le pansement compressif sont inefficaces.","ref":{"d":"b2002","p":216},"choices":["Une compression directe","Poser un garrot d'emblée","Surélever la tête"]},{"id":"s:ssuap:31","g":"ssuap","k":"vf","q":"Lors d'une hémorragie, le port de gants à usage unique est systématique.","answer":true,"explication":"Oui, gants systématiques, et masque plus lunettes en cas de risque de projection. On se protège pour continuer à protéger.","ref":{"d":"b2002","p":216}},{"id":"s:ssuap:32","g":"ssuap","k":"qcm","q":"Quelle victime doit être installée en PLS ?","answer":1,"explication":"La PLS est pour la victime inconsciente qui respire : elle garde les voies aériennes libres. En arrêt cardiaque, c'est la RCP.","ref":{"d":"b2002","p":589},"choices":["Une victime consciente qui respire bien","Une victime inconsciente qui respire","Une victime en arrêt cardiaque"]},{"id":"s:ssuap:33","g":"ssuap","k":"vf","q":"Le sapeur-pompier réalise un bilan secouriste et établit un diagnostic médical.","answer":false,"explication":"Faux : il réalise un bilan secouriste mais n'établit pas de diagnostic médical. Il n'est ni médecin, ni infirmier.","ref":{"d":"b2002","p":39}},{"id":"s:ssuap:34","g":"ssuap","k":"qcm","q":"Au-delà de combien de victimes visuellement graves applique-t-on les principes de base du triage ?","answer":2,"explication":"Au-delà de 5 victimes visuellement graves (inertes, brûlées...), on applique les principes de base du triage du chapitre 19.","ref":{"d":"b2002","p":140},"choices":["Plus de 2","Plus de 50","Plus de 5"]},{"id":"s:acr:0","g":"acr","k":"qcm","q":"Par quel trouble du rythme débutent environ 80 % des arrêts cardiaques ?","answer":1,"explication":"80 % des ACR débutent par une FV : c'est justement le rythme que le défibrillateur sait traiter par un choc. D'où l'intérêt de le poser vite !","ref":{"d":"acr72","p":1},"choices":["L'asystolie","La fibrillation ventriculaire","La tachycardie sinusale"]},{"id":"s:acr:1","g":"acr","k":"qcm","q":"Privé d'oxygène, combien de temps le cerveau tient-il avant des lésions graves ?","answer":2,"explication":"Le cerveau est l'organe le plus fragile : 2 à 4 minutes seulement. Le cœur tient 15 à 30 min, le foie jusqu'à 80 min.","ref":{"d":"acr72","p":2},"choices":["15 à 30 minutes","40 à 80 minutes","2 à 4 minutes"]},{"id":"s:acr:2","g":"acr","k":"qcm","q":"Comment appelle-t-on le temps pendant lequel le cœur est arrêté et non massé ?","answer":0,"explication":"No flow = pas de circulation du tout. Dès qu'on masse, on passe en low flow (circulation ralentie).","ref":{"d":"acr72","p":2},"choices":["Le no flow","Le low flow","Le time keeper"]},{"id":"s:acr:3","g":"acr","k":"qcm","q":"Chez l'adulte en ACR, quel est le rythme d'un cycle de RCP ?","answer":1,"explication":"Chez l'adulte : 30/2. Chez l'enfant, le nourrisson et le nouveau-né, les sapeurs-pompiers font 15/2.","ref":{"d":"acr72","p":5},"choices":["15 compressions, 2 insufflations","30 compressions, 2 insufflations","3 compressions, 1 insufflation"]},{"id":"s:acr:4","g":"acr","k":"vf","q":"Seul un médecin peut ordonner aux sapeurs-pompiers d'arrêter les manœuvres de RCP.","answer":true,"explication":"Exact : l'arrêt de la RCP ne peut être ordonné que par un médecin. Avant, on masse, on masse, on masse.","ref":{"d":"acr72","p":6}},{"id":"s:acr:5","g":"acr","k":"qcm","q":"Chaque minute perdue avant la défibrillation réduit les chances de survie de…","answer":2,"explication":"7 à 10 % par minute : le temps est vraiment l'ennemi. D'où l'importance de poser le DAE sans retarder la RCP.","ref":{"d":"ft231","p":1},"choices":["1 à 2 %","25 %","7 à 10 %"]},{"id":"s:acr:6","g":"acr","k":"vf","q":"Sur un enfant, si tu n'as que des patchs de défibrillation adultes, tu as le droit de les utiliser.","answer":true,"explication":"Oui, c'est autorisé. Ils se posent alors en antéro-postérieur : un dans le dos entre les omoplates, l'autre devant au milieu du thorax.","ref":{"d":"ft231","p":2}},{"id":"s:acr:7","g":"acr","k":"qcm","q":"Pourquoi place-t-on le DAE près de la tête de la victime ?","answer":1,"explication":"Le sapeur-pompier aux insufflations doit entendre les consignes vocales du DAE. Malin et pratique !","ref":{"d":"ft231","p":4},"choices":["Pour qu'il ne prenne pas l'eau","Pour que celui qui insuffle entende les messages vocaux","Pour que la famille le voie"]},{"id":"s:acr:8","g":"acr","k":"qcm","q":"Après un ACR choqué, où doit être ramené le DAE civil (public ou privé) ?","answer":0,"explication":"Il est ramené au PVO du CSTC pour extraire ses données médicales, sauf ceux des ambulances privées, du SAMU ou des associations agréées.","ref":{"d":"daecivil","p":2},"choices":["Au PVO du CSTC","À la mairie","Chez le fabricant"]},{"id":"s:acr:9","g":"acr","k":"vf","q":"Le défibrillateur civil emporté par les pompiers est rendu à son propriétaire sous 5 jours ouvrés.","answer":true,"explication":"C'est ce que promet la fiche remise au propriétaire : 5 jours ouvrés, le temps d'extraire les données médicales.","ref":{"d":"daecivil","p":2}},{"id":"s:acr:10","g":"acr","k":"qcm","q":"Douleur thoracique, ECG en cours, et la victime perd connaissance : que fais-tu ?","answer":2,"explication":"Dans ce contexte, la probabilité d'une FV est très élevée : analyse DSA immédiate, c'est une action de sauvegarde.","ref":{"d":"dsa","p":1},"choices":["Je refais un ECG","Je mets en PLS et je surveille","Analyse DSA sans délai, sans bilan primaire"]},{"id":"s:acr:11","g":"acr","k":"vf","q":"Chez une personne inconsciente, on peut se fier à l'activité ECG affichée sur l'écran du DGT7.","answer":false,"explication":"C'est interdit ! Une activité électrique à l'écran peut tromper alors que la victime est en ACR. Pouls carotidien et DSA font foi.","ref":{"d":"dsa","p":1}},{"id":"s:acr:12","g":"acr","k":"qcm","q":"À partir de quelle température centrale l'hyperthermie devient-elle dangereuse ?","answer":1,"explication":"Le cerveau maintient le corps à 37 °C ; le danger commence à partir de 40 °C.","ref":{"d":"chaleur","p":4},"choices":["37 °C","40 °C","38 °C"]},{"id":"s:acr:13","g":"acr","k":"qcm","q":"Coup de chaleur d'exercice : à quelle température peut-on évacuer la victime ?","answer":0,"explication":"Priorité 1 : refroidir. Priorité 2 : évacuer quand la température est passée sous 38,5 °C.","ref":{"d":"chaleur","p":12},"choices":["Quand elle est sous 38,5 °C","Tout de suite, sans attendre","Quand elle est sous 40 °C"]},{"id":"s:acr:14","g":"acr","k":"qcm","q":"Laquelle de ces pathologies liées à la chaleur fait partie des trois du BSP 200.2 ?","answer":1,"explication":"Le BSP 200.2 distingue l'insolation, l'épuisement hyperthermique et le coup de chaleur. L'engelure, elle, préfère l'hiver.","ref":{"d":"chaleur2","p":1},"choices":["L'engelure","L'épuisement hyperthermique","Le mal des montagnes"]},{"id":"s:acr:15","g":"acr","k":"qcm","q":"De quoi se compose le lot « coup de chaleur » ?","answer":0,"explication":"Glace pour refroidissement (20 kg de glaçons) et brancard baignoire pour immerger la victime.","ref":{"d":"chaleur2","p":2},"choices":["De glace et d'un brancard baignoire","D'un ventilateur et de bouteilles d'eau","De couvertures de survie"]},{"id":"s:acr:16","g":"acr","k":"vf","q":"L'immersion dans l'eau froide avec de la glace est le traitement de référence du coup de chaleur.","answer":true,"explication":"Oui ! Ventiler ou humidifier n'est qu'une solution d'attente. Le refroidissement massif est au coup de chaleur ce que la RCP est à l'ACR.","ref":{"d":"chaleur2","p":4}},{"id":"s:acr:17","g":"acr","k":"qcm","q":"Lors de la réanimation du nouveau-né à la naissance, qui est « à la respiration » ?","answer":1,"explication":"C'est le chef d'agrès : il se place à la tête du nouveau-né et facilite la mise en route de la respiration.","ref":{"d":"nnn","p":3},"choices":["L'équipier logistique","Le chef d'agrès","La maman"]},{"id":"s:acr:18","g":"acr","k":"qcm","q":"Dans la réanimation du nouveau-né, que veut dire le « B » des phases A, B, C ?","answer":2,"explication":"A = Airway (voies aériennes), B = Breathing (ventilations), C = Circulation (RCP). Un peu d'anglais pour la bonne cause !","ref":{"d":"nnn","p":8},"choices":["Bilan","Brancard","Breathing"]},{"id":"s:acr:19","g":"acr","k":"qcm","q":"À qui est destiné le message radio 4C-N lors d'un ACR ?","answer":0,"explication":"Le 4C-N informe la coordination médicale pour ajuster l'envoi des moyens, notamment l'équipe ECMO.","ref":{"d":"macaacr","p":21},"choices":["À la coordination médicale","Au service des urgences","À la famille de la victime"]},{"id":"s:acr:20","g":"acr","k":"qcm","q":"Le requérant masse, son DAE public a déjà choqué. Que fais-tu du DAE ?","answer":2,"explication":"On change et on met notre DSA : les DAE publics sont beaucoup plus lents dans leurs analyses et leurs ordres.","ref":{"d":"macaacr","p":10},"choices":["Je le laisse, il marche bien","Je l'éteins et j'attends","Je le remplace par notre DSA"]},{"id":"s:acr:21","g":"acr","k":"vf","q":"Quand le DSA propose un choc, seul le chef d'agrès a le droit d'appuyer sur le bouton.","answer":false,"explication":"Tout le monde peut choquer, même les équipiers ! Doigt sur le bouton pendant l'analyse et on choque sans attendre la fin du message.","ref":{"d":"macaacr","p":20}},{"id":"s:acr:22","g":"acr","k":"qcm","q":"Quel nouveau dispositif remplace la cardiopompe pour contrôler la qualité du massage ?","answer":0,"explication":"La cardiopompe n'est plus produite : le LifePoint arrive, en commençant par le G3.","ref":{"d":"macaacr","p":33},"choices":["Le LifePoint","La Life Vest","Le DGT7"]},{"id":"s:acr:23","g":"acr","k":"qcm","q":"La Life Vest sonne et le patient est conscient : que fait-il pour annuler le choc ?","answer":1,"explication":"Patient conscient : il appuie sur les 2 boutons. S'il est inconscient, le gilet délivre le choc.","ref":{"d":"lifevest","p":2},"choices":["Il retire la batterie","Il appuie sur les 2 boutons du boîtier","Il enlève le gilet"]},{"id":"s:acr:24","g":"acr","k":"vf","q":"Pour l'opérateur 18, une Life Vest qui émet plusieurs alarmes doit entraîner une procédure rouge.","answer":true,"explication":"Plusieurs alarmes (ou un DAI qui choque plusieurs fois) sont des signes précurseurs d'un ACR : procédure rouge.","ref":{"d":"lifevest","p":2}},{"id":"s:acr:25","g":"acr","k":"qcm","q":"Une victime à transporter a un chien guide d'aveugle : qui le COS demande-t-il ?","answer":2,"explication":"Le COS demande le groupe risque animalier, qui arme le VRA (Véhicule Risque Animalier). Le fidèle compagnon est bien pris en charge.","ref":{"d":"chiens","p":2},"choices":["La fourrière","Un deuxième VSAV","Le groupe risque animalier"]},{"id":"s:acr:26","g":"acr","k":"vf","q":"Le chien d'assistance peut être déposé n'importe où, même hors du secteur de la BSPP.","answer":false,"explication":"Non : le lieu de dépôt se situe obligatoirement sur le secteur de compétence de la BSPP.","ref":{"d":"chiens","p":2}},{"id":"s:acr:27","g":"acr","k":"qcm","q":"Pour photographier un ECG sur l'écran du DGT7, combien de clichés faut-il ?","answer":1,"explication":"4 clichés en balayage vertical pour voir les 12 dérivations. Et désormais, le couplage DGT7-tablette est préférable.","ref":{"d":"reveil","p":1},"choices":["1 seul","4, avec un balayage vertical","12, un par dérivation"]},{"id":"s:acr:28","g":"acr","k":"vf","q":"Dans la fiche « Réveil », la victime s'est réveillée après un massage immédiat et 3 chocs.","answer":true,"explication":"Oui : le CA a massé sans attendre, 3 CEE ont été délivrés, puis la victime s'est réveillée. Une belle histoire qui finit bien !","ref":{"d":"reveil","p":1}},{"id":"s:acr:29","g":"acr","k":"qcm","q":"En traumatologie, une vitesse de 50 km/h équivaut à une chute de…","answer":1,"explication":"50 km/h = chute de 10 m. La cinétique compte : ne jamais la négliger dans le bilan !","ref":{"d":"trauma","p":7},"choices":["2 mètres","10 mètres","30 mètres"]},{"id":"s:acr:30","g":"acr","k":"qcm","q":"Selon la « Golden Hour », 10 minutes de plus hors de l'hôpital, c'est…","answer":0,"explication":"10 minutes hors de l'hôpital = 4 % de mortalité en plus. Il faut donc anticiper relevage, immobilisation et transport.","ref":{"d":"trauma","p":45},"choices":["4 % de mortalité en plus","Aucun impact","50 % de mortalité en plus"]},{"id":"s:acr:31","g":"acr","k":"vf","q":"Plus une plaie par lame est petite, moins elle est profonde.","answer":false,"explication":"C'est l'inverse : plus la plaie est petite, plus la lame a pu aller en profondeur. Une estafilade n'est pas une plaie pénétrante.","ref":{"d":"trauma","p":4}},{"id":"s:acr:32","g":"acr","k":"qcm","q":"Que veut dire « fortuit » quand on parle d'une chute ?","answer":1,"explication":"Fortuit veut dire imprévu… donc toutes les chutes le sont ! Le mot ne dit rien de la cause.","ref":{"d":"chutes","p":3},"choices":["Grave","Imprévu","Mécanique"]},{"id":"s:acr:33","g":"acr","k":"vf","q":"Chez la personne âgée, la chute mécanique (par maladresse) est la cause la plus fréquente.","answer":false,"explication":"Faux : la chute mécanique est RARE chez la personne âgée. La chute est très souvent le symptôme d'une maladie.","ref":{"d":"chutes","p":5}},{"id":"s:acr:34","g":"acr","k":"qcm","q":"Personne âgée restée des heures au sol sans bouger : quel risque guette ?","answer":1,"explication":"Les points de compression prolongés exposent au crush syndrome. Sans oublier déshydratation et hypothermie.","ref":{"d":"chutes","p":7},"choices":["Le coup de chaleur","Le crush syndrome","L'insolation"]},{"id":"s:efibi:0","g":"efibi","k":"qcm","q":"Que signifie le nom eFiBi ?","answer":0,"explication":"eFiBi, c'est la Fiche Bilan électronique : les bilans des victimes se font sur tablette et remplacent les fiches papier.","ref":{"d":"efibi","p":2},"choices":["Fiche Bilan électronique","Fichier des bilans infirmiers","Fiche d'identification des binômes"]},{"id":"s:efibi:1","g":"efibi","k":"qcm","q":"Quel appareil envoie l'ECG et les constantes vers la tablette eFiBi ?","answer":1,"explication":"Une fois appariée au DGT-7, la tablette récupère automatiquement constantes et ECG. Moins de saisie, plus de temps pour la victime.","ref":{"d":"efibi","p":9},"choices":["La radio TPH 700","Le moniteur multiparamétrique DGT-7","L'application Waze"]},{"id":"s:efibi:2","g":"efibi","k":"vf","q":"Dans Waze, on choisit le mode de conduite « Taxi » pour avoir un trajet adapté, avec passage possible sur les voies de bus.","answer":true,"explication":"Le mode « Taxi » propose un trajet adapté aux véhicules de secours, voies de bus comprises. Pas besoin de licence de taxi !","ref":{"d":"efibi","p":11}},{"id":"s:efibi:3","g":"efibi","k":"qcm","q":"Pour un accouchement, combien de prises en charge faut-il remplir dans eFiBi ?","answer":2,"explication":"Deux prises en charge obligatoires : une pour la maman, une pour le nouveau-né. Le bébé a droit à sa propre fiche dès le premier jour.","ref":{"d":"efibi","p":24},"choices":["Une seule","Trois","Deux"]},{"id":"s:efibi:4","g":"efibi","k":"vf","q":"Si les antécédents de la victime sont inconnus, on peut laisser l'onglet MHTA vide.","answer":false,"explication":"L'onglet MHTA doit être renseigné même si les antécédents sont inconnus : l'absence de renseignements doit être notée.","ref":{"d":"efibi","p":18}},{"id":"s:efibi:5","g":"efibi","k":"qcm","q":"En cas d'Urgence Absolue, que faut-il au minimum noter pour l'identité de la victime ?","answer":0,"explication":"En UA, pas le temps pour tout : au minimum l'âge approximatif et le sexe. Le reste pourra être complété plus tard.","ref":{"d":"efibi","p":15},"choices":["Son âge approximatif et son sexe","Son numéro de sécurité sociale","Son adresse complète"]},{"id":"s:efibi:6","g":"efibi","k":"qcm","q":"Les constantes utilisées pour le bilan du chef d'agrès doivent dater de moins de…","answer":1,"explication":"Quelle que soit la gravité, le bilan se fait avec des constantes prises il y a moins de 10 minutes (BSP 200.2).","ref":{"d":"recap","p":1},"choices":["5 minutes","10 minutes","30 minutes"]},{"id":"s:efibi:7","g":"efibi","k":"qcm","q":"Qui réalise les mises à jour système et applications des tablettes eFiBi ?","answer":2,"explication":"Le stationnaire du PVO fait les mises à jour manuellement dès réception du message. La victime a d'autres soucis !","ref":{"d":"recap","p":1},"choices":["Le conducteur du VSAV","La victime","Le stationnaire du PVO"]},{"id":"s:efibi:8","g":"efibi","k":"qcm","q":"Quel jour le référent eFiBi du centre de secours contrôle-t-il les tablettes ?","answer":0,"explication":"Le contrôle a lieu tous les jeudis, comme les mises à jour SINUS, pour vérifier notamment que les mises à jour sont faites.","ref":{"d":"recap","p":2},"choices":["Le jeudi","Le lundi","Le dimanche"]},{"id":"s:efibi:9","g":"efibi","k":"qcm","q":"Que signifie le sigle IRCS ?","answer":1,"explication":"IRCS : Intervention Revêtant un Caractère Social. Le but est de transmettre les situations sociales aux bons partenaires.","ref":{"d":"ircs","p":1},"choices":["Intervention Rapide en Cas de Secours","Intervention Revêtant un Caractère Social","Inventaire des Risques Chimiques et Sanitaires"]},{"id":"s:efibi:10","g":"efibi","k":"vf","q":"Si tu oublies de saisir le type de victime « SDF », le signalement IRCS sera quand même transmis au Samu social.","answer":false,"explication":"Sans le type « SDF », le bon formulaire n'apparaît pas et le signalement ne sera jamais transmis au Samu social.","ref":{"d":"ircs","p":6}},{"id":"s:efibi:11","g":"efibi","k":"qcm","q":"Sans quelle information les services sociaux ne pourront pas contacter la personne signalée ?","answer":2,"explication":"Sans au moins un numéro de téléphone, les services sociaux ne peuvent pas entrer en contact avec la personne.","ref":{"d":"ircs","p":7},"choices":["Son groupe sanguin","Sa plaque d'immatriculation","Un numéro de téléphone"]},{"id":"s:efibi:12","g":"efibi","k":"qcm","q":"À quoi correspond le Mode Dégradé 5 (MD5) ?","answer":0,"explication":"MD5 = ADAGIO indisponible à tous les niveaux (CO, CSO et PVO). eFiBi, lui, continue de fonctionner.","ref":{"d":"md5","p":3},"choices":["À l'indisponibilité de toutes les applications ADAGIO","À une tablette déchargée","À une panne du DGT-7"]},{"id":"s:efibi:13","g":"efibi","k":"vf","q":"En MD5, la prise en charge dans eFiBi reste la même ; seule la création du numéro d'intervention se fait manuellement.","answer":true,"explication":"On appuie sur +, puis sur MD5 pour générer le numéro d'intervention. Le reste est identique au mode normal.","ref":{"d":"md5","p":3}},{"id":"s:efibi:14","g":"efibi","k":"qcm","q":"Pour une victime en ACR à l'arrivée, quelle action génère le cahier ACR dématérialisé ?","answer":1,"explication":"C'est la sélection du motif ACR qui génère le cahier ACR, à remplir obligatoirement lors de la prise en charge d'un ACR.","ref":{"d":"tutoarr","p":4},"choices":["Prendre une photo de la victime","Sélectionner le motif de recours ACR","Clôturer l'intervention"]},{"id":"s:efibi:15","g":"efibi","k":"vf","q":"Si une victime tombe en ACR pendant ton bilan, tu ajoutes le motif ACR comme motif de recours supplémentaire.","answer":true,"explication":"On garde le motif initial (ex. douleur thoracique) et on ajoute le motif ACR : le cahier ACR s'ouvre alors.","ref":{"d":"tutobil","p":5}},{"id":"s:efibi:16","g":"efibi","k":"qcm","q":"Par quoi est remplacé l'ancien tutoriel « vider le cache » de la tablette ?","answer":2,"explication":"On supprime désormais complètement les données : plus rapide que les 7 clics d'avant, et plus efficace contre les bugs.","ref":{"d":"suppr","p":2},"choices":["Réinstaller eFiBi chaque jour","Cliquer 7 fois sur le même onglet","Supprimer complètement les données"]},{"id":"s:efibi:17","g":"efibi","k":"qcm","q":"Le 11 novembre 2025, sur 44 interventions avec UMH, combien avaient la photo de l'observation UMH ?","answer":0,"explication":"Seulement 5 sur 44 ! Pense à demander au médecin l'autorisation de photographier son observation.","ref":{"d":"macaefibi","p":3},"choices":["5","30","44"]},{"id":"s:efibi:18","g":"efibi","k":"vf","q":"Il faut avoir rempli complètement eFiBi avant de demander une équipe médicale au bilan primaire.","answer":false,"explication":"Pas besoin de remplir complètement eFiBi pour demander une équipe médicale. Il faut quand même savoir justifier sa demande.","ref":{"d":"macaefibi","p":4}},{"id":"s:efibi:19","g":"efibi","k":"qcm","q":"Que faut-il avoir renseigné pour que les constantes anormales s'affichent en couleur ?","answer":1,"explication":"Sans l'âge, eFiBi ne peut pas savoir ce qui est anormal. Avec, les valeurs inquiétantes sautent aux yeux.","ref":{"d":"macaefibi","p":5},"choices":["Le nom de la victime","L'âge de la victime","L'adresse de l'intervention"]},{"id":"s:efibi:20","g":"efibi","k":"qcm","q":"À quoi sert un masque FFP2 ?","answer":2,"explication":"Le FFP2 protège celui qui le porte ; le masque chirurgical protège surtout les autres.","ref":{"d":"macaintro","p":5},"choices":["À filtrer les fumées d'incendie","À protéger les autres des gouttelettes du porteur","À protéger le porteur des gouttelettes des autres"]},{"id":"s:efibi:21","g":"efibi","k":"vf","q":"Lors des formations MACA, les écoutes d'appels à la coordination médicale peuvent être diffusées hors séance.","answer":false,"explication":"Aucune diffusion hors séance : bienveillance, anonymat respecté, et un seul objectif, améliorer les pratiques.","ref":{"d":"macaintro","p":2}},{"id":"s:efibi:22","g":"efibi","k":"qcm","q":"Sur intervention, qui demande la police par message radio ?","answer":0,"explication":"C'est le commandant des opérations de secours (COS) qui demande la police, au vu de la réalité constatée sur place.","ref":{"d":"police","p":3},"choices":["Le COS","La victime","Le requérant"]},{"id":"s:efibi:23","g":"efibi","k":"qcm","q":"Dans la nouvelle procédure, à quel moment le COS peut-il redemander la police ?","answer":1,"explication":"La phase de redemande passe à T+10, au lieu de T+15 dans l'ancienne procédure.","ref":{"d":"police","p":5},"choices":["À T+35 minutes","À T+10 minutes","À T+60 minutes"]},{"id":"s:efibi:24","g":"efibi","k":"vf","q":"Un accident matériel de la circulation sans blessé ni dégât au domaine public nécessite la présence de la police.","answer":false,"explication":"La DSPAP rappelle que ce cas ne nécessite pas la police : elle se concentre sur les demandes vraiment utiles.","ref":{"d":"police","p":3}},{"id":"s:efibi:25","g":"efibi","k":"qcm","q":"À quoi sert l'imprimé BOPE 24 ?","answer":2,"explication":"Il fait signer par l'autorité l'autorisation pour les pompiers de Paris d'entrer dans une ambassade, un consulat ou une légation.","ref":{"d":"ambassade","p":1},"choices":["À demander un renfort GRIMP","À transmettre un bilan à l'hôpital","À obtenir l'autorisation d'entrer dans une ambassade, un consulat ou une légation"]},{"id":"s:efibi:26","g":"efibi","k":"qcm","q":"Quand laisse-t-on le « papillon jaune » (BOPE 13) ?","answer":0,"explication":"Il informe l'occupant que les pompiers sont entrés chez lui pendant son absence, et comment obtenir le rapport.","ref":{"d":"papillon","p":1},"choices":["Quand les pompiers sont entrés dans des locaux en l'absence de l'occupant","Quand une victime refuse son transport","Quand le VSAV est mal garé"]},{"id":"s:efibi:27","g":"efibi","k":"vf","q":"N'importe quel voisin peut demander une copie du rapport d'intervention indiqué sur le papillon jaune.","answer":false,"explication":"La demande doit être faite par l'intéressé ou un ayant droit (lien de parenté ou de tutelle), avec justificatifs.","ref":{"d":"papillon","p":1}},{"id":"s:efibi:28","g":"efibi","k":"qcm","q":"À Paris, à qui sont transmis les signalements sociaux des chefs d'agrès ?","answer":1,"explication":"À Paris, c'est le centre d'action sociale de la Ville ; en petite couronne, ce sont les conseils départementaux.","ref":{"d":"vie","p":1},"choices":["Au commissariat le plus proche","Au centre d'action sociale de la Ville de Paris","À l'hôpital receveur"]},{"id":"s:efibi:29","g":"efibi","k":"vf","q":"Après un signalement social, un travailleur social contacte la personne et lui rend visite à domicile.","answer":true,"explication":"Le signalement transmis grâce au rapport d'intervention déclenche le contact et la visite d'un travailleur social.","ref":{"d":"vie","p":1}},{"id":"s:efibi:30","g":"efibi","k":"qcm","q":"Depuis le 01/09/2025, que devient la partie victime du rapport d'intervention si une eFiBi a été rédigée ?","answer":2,"explication":"Objectif simplification : si une eFiBi existe, la partie victime du rapport d'intervention est supprimée.","ref":{"d":"mcori","p":6},"choices":["Elle est remplie deux fois","Elle est faite sur papier","Elle est supprimée"]},{"id":"s:efibi:31","g":"efibi","k":"qcm","q":"Quelle radio le TPH 700 remplace-t-il ?","answer":0,"explication":"Le TPH 700 est une radio portative numérique nouvelle génération qui remplace le GP360 de Motorola.","ref":{"d":"tph","p":2},"choices":["Le GP360 de Motorola","Le DGT-7","Le talkie du GRIMP"]},{"id":"s:efibi:32","g":"efibi","k":"qcm","q":"Comment allume-t-on le TPH 700 ?","answer":1,"explication":"Appui long sur la touche verte ON/OFF/Prise d'appel jusqu'à ce que la LED verte s'allume.","ref":{"d":"tph","p":5},"choices":["Appui court sur la touche rouge","Appui long sur la touche verte jusqu'à la LED verte","En tournant le bouton rotacteur"]},{"id":"s:efibi:33","g":"efibi","k":"qcm","q":"Que signifie GRIMP ?","answer":2,"explication":"GRIMP : Groupe de Reconnaissance et d'Intervention en Milieu Périlleux. Des experts de la hauteur et des profondeurs.","ref":{"d":"grimp","p":1},"choices":["Groupe Rapide d'Intervention Médicale de Proximité","Groupe de Recherche et d'Information Médicale de Paris","Groupe de Reconnaissance et d'Intervention en Milieu Périlleux"]},{"id":"s:efibi:34","g":"efibi","k":"vf","q":"Le GRIMP ne s'occupe que d'interventions spectaculaires : inutile de le solliciter pour un brancardage compliqué.","answer":false,"explication":"Au contraire : il est très efficace pour les brancardages en milieux complexes. N'aie pas peur de « déranger » !","ref":{"d":"grimp","p":1}},{"id":"s:bsp:0","g":"bsp","k":"qcm","q":"Quel est le sujet du BSP 115.1 ?","answer":1,"explication":"Le BSP 115.1 explique comment la Brigade choisit et envoie ses moyens : règles d'engagement, départs types, ordre de départ.","ref":{"d":"b1151","p":1},"choices":["Le service intérieur en caserne","L'engagement des secours","Les tenues NRBC"]},{"id":"s:bsp:1","g":"bsp","k":"qcm","q":"Que signifie le sigle PVO ?","answer":2,"explication":"Le PVO est le poste de veille opérationnelle du centre de secours : c'est son stationnaire qui fait partir les engins.","ref":{"d":"b1151","p":91},"choices":["Patrouille de véhicules opérationnels","Point de vigilance organisé","Poste de veille opérationnelle"]},{"id":"s:bsp:2","g":"bsp","k":"qcm","q":"Le départ normal (DN), réponse initiale à tout feu, comprend…","answer":0,"explication":"Le DN = 2 EP + 1 moyen élévateur aérien (MEA) + 1 ventilateur opérationnel (VO). Il est commandé par un chef de garde.","ref":{"d":"b1151","p":15},"choices":["2 engins-pompes, un MEA et un ventilateur","1 VSAV et 1 VID","3 échelles et rien d'autre"]},{"id":"s:bsp:3","g":"bsp","k":"vf","q":"Un ordre de départ (ODE) peut être différé librement par le stationnaire du PVO.","answer":false,"explication":"Faux : l'ODE est un ordre immédiatement exécutable, modifiable seulement à titre exceptionnel. Pas le temps de finir son café !","ref":{"d":"b1151","p":17}},{"id":"s:bsp:4","g":"bsp","k":"vf","q":"Dans le jargon BSPP, CSO signifie « centre de suivi opérationnel ».","answer":true,"explication":"Vrai. Le CSO suit les interventions de son groupement ; « CSO TC » désigne le CSO territorialement compétent.","ref":{"d":"b1151","p":89}},{"id":"s:bsp:5","g":"bsp","k":"qcm","q":"Quel est le sujet du BSP 115.2 ?","answer":2,"explication":"Le BSP 115.2 traite de la conduite de l'opération : aide au commandement, renforts, messagerie opérationnelle…","ref":{"d":"b1152","p":1},"choices":["Le catalogue des engins","La vie en caserne","La conduite de l'opération"]},{"id":"s:bsp:6","g":"bsp","k":"qcm","q":"Dans le réseau radio dirigé de la Brigade, qui est la station directrice primaire ?","answer":1,"explication":"Le CO (centre opérationnel) est la station primaire, les CSO sont secondaires et les PVO tertiaires.","ref":{"d":"b1152","p":13},"choices":["Le PVO","Le CO","Le VSAV"]},{"id":"s:bsp:7","g":"bsp","k":"qcm","q":"Combien de types de messages opérationnels le BSP 115.2 distingue-t-il ?","answer":0,"explication":"8 types : départ, présentation, demande de moyens, ambiance, renseignements, déplacement, disponibilité et rentrée.","ref":{"d":"b1152","p":87},"choices":["8","3","15"]},{"id":"s:bsp:8","g":"bsp","k":"qcm","q":"Le message d'ambiance répond avant tout à la question…","answer":0,"explication":"Il décrit succinctement la situation constatée, les risques avérés et si possible l'évolution envisageable. On reste factuel !","ref":{"d":"b1152","p":93},"choices":["« De quoi s'agit-il ? »","« Qui a appelé les secours ? »","« À quelle heure rentre-t-on ? »"]},{"id":"s:bsp:9","g":"bsp","k":"vf","q":"Le message d'ambiance se passe de préférence dans les 10 minutes qui suivent la présentation sur les lieux.","answer":true,"explication":"Vrai : il sert à alerter ou rassurer rapidement le commandement, de préférence dans les 10 min après s'être présenté.","ref":{"d":"b1152","p":93}},{"id":"s:bsp:10","g":"bsp","k":"qcm","q":"À quoi sert le BSP 115.3 ?","answer":1,"explication":"Il décrit les modes dégradés quand ADAGIO, ANTARES ou la téléphonie tombent en panne, pour que les secours partent quand même.","ref":{"d":"b1153","p":7},"choices":["À lister les engins de la Brigade","À gérer les pannes des systèmes (modes dégradés)","À organiser le service de jour"]},{"id":"s:bsp:11","g":"bsp","k":"qcm","q":"Le mode dégradé 1 (MD 1) ADAGIO correspond à…","answer":2,"explication":"MD 1 = PVO indisponible. Le stationnaire ressort alors les fiches et le cahier de départ des secours papier.","ref":{"d":"b1153","p":11},"choices":["La panne générale du CO","Une panne de VSAV","L'indisponibilité d'un ou plusieurs PVO"]},{"id":"s:bsp:12","g":"bsp","k":"vf","q":"Le mode dégradé 2 correspond à l'indisponibilité d'un ou plusieurs CSO.","answer":true,"explication":"Vrai : le CSO est alors isolé du CO et de ses PVO ; un CSO Back-up est armé pour prendre le relais.","ref":{"d":"b1153","p":13}},{"id":"s:bsp:13","g":"bsp","k":"vf","q":"En mode dégradé 3 (CO sanctuarisé), le CO continue d'envoyer les ordres de départ aux CSO et PVO via ADAGIO.","answer":false,"explication":"Faux : en MD 3, ADAGIO fonctionne « en local » au CO mais ne transmet plus d'ODE vers le réseau CSO-PVO.","ref":{"d":"b1153","p":17}},{"id":"s:bsp:14","g":"bsp","k":"vf","q":"En mode dégradé 5, ADAGIO est indisponible à tous les niveaux : CO, CSO et PVO.","answer":true,"explication":"Vrai, c'est le mode le plus sévère : les STATUS ANTARES sont HS et tous les messages passent en phonie.","ref":{"d":"b1153","p":21}},{"id":"s:bsp:15","g":"bsp","k":"qcm","q":"Le BSP 118 (ROFSIS) porte sur…","answer":1,"explication":"ROFSIS = règlement sur l'organisation et le fonctionnement du service d'incendie et de secours. Un vrai « mode d'emploi » de la Brigade.","ref":{"d":"b118","p":1},"choices":["Les tenues NRBC","L'organisation et le fonctionnement du service d'incendie et de secours","Le catalogue des engins"]},{"id":"s:bsp:16","g":"bsp","k":"qcm","q":"Combien de communes la BSPP défend-elle ?","answer":0,"explication":"124 communes : Paris et les trois départements de la petite couronne (92, 93 et 94).","ref":{"d":"b118","p":16},"choices":["124","36","1 200"]},{"id":"s:bsp:17","g":"bsp","k":"qcm","q":"Sur intervention, qui met en œuvre tous les moyens engagés, sous l'autorité du DOS ?","answer":2,"explication":"Le commandant des opérations de secours (COS) agit sous l'autorité du DOS, le préfet de police ou l'autorité déléguée.","ref":{"d":"b118","p":29},"choices":["Le stationnaire du PVO","Le sergent de jour","Le COS"]},{"id":"s:bsp:18","g":"bsp","k":"qcm","q":"Accident impliquant ton engin en route vers l'intervention : que fait le chef d'agrès pour limiter le retard ?","answer":1,"explication":"Il limite le retard dans l'arrivée des secours en demandant au CSO de faire partir un autre moyen en remplacement.","ref":{"d":"b118","p":42},"choices":["Il rentre au centre de secours","Il demande au CSO de faire partir un autre moyen en remplacement","Il attend la dépanneuse sans rien dire"]},{"id":"s:bsp:19","g":"bsp","k":"qcm","q":"Quelle est la devise des sapeurs-pompiers de Paris ?","answer":0,"explication":"« Sauver ou périr » : elle rappelle le devoir de secourir, même si la sécurité du sapeur-pompier reste une préoccupation de tous les instants.","ref":{"d":"b118","p":37},"choices":["« Sauver ou périr »","« Courage et dévouement »","« Toujours prêts »"]},{"id":"s:bsp:20","g":"bsp","k":"vf","q":"Au retour d'intervention, les avertisseurs sonores et lumineux sont autorisés pour rentrer plus vite.","answer":false,"explication":"Faux : leur usage est strictement interdit au retour. On respecte le code de la route comme tout le monde !","ref":{"d":"b118","p":42}},{"id":"s:bsp:21","g":"bsp","k":"qcm","q":"Le BSP 112, règlement sur le service intérieur, organise surtout…","answer":1,"explication":"Il organise la vie en casernement, les rassemblements et les activités qui rythment la journée (instruction, repas…).","ref":{"d":"b112","p":11},"choices":["Le paramétrage d'ADAGIO","La vie dans les casernements et les activités quotidiennes","Les opérations NRBC"]},{"id":"s:bsp:22","g":"bsp","k":"qcm","q":"Selon le BSP 112, la plus petite formation placée sous les ordres d'un chef responsable est…","answer":2,"explication":"La compagnie : c'est l'échelon le plus élevé où chacun peut connaître tous les autres et en être connu.","ref":{"d":"b112","p":11},"choices":["Le groupement","La brigade","La compagnie"]},{"id":"s:bsp:23","g":"bsp","k":"vf","q":"Le service de jour de la compagnie comprend un sergent de jour et un gradé de jour.","answer":true,"explication":"Vrai : le sergent de jour, secondé par le gradé de jour, garantit notamment l'armement permanent des engins.","ref":{"d":"b112","p":25}},{"id":"s:bsp:24","g":"bsp","k":"qcm","q":"Combien de temps dure le service de jour ?","answer":0,"explication":"24 heures, de 7 h 45 à 7 h 45 le lendemain. Mieux vaut avoir bien dormi la veille !","ref":{"d":"b112","p":25},"choices":["24 heures","12 heures","48 heures"]},{"id":"s:bsp:25","g":"bsp","k":"qcm","q":"Que trouve-t-on dans le BSP 300.16 ?","answer":0,"explication":"C'est le catalogue des moyens : une fiche par engin (caractéristiques, observations, matériels majeurs), du CA au VSAV.","ref":{"d":"b30016","p":4},"choices":["Des fiches décrivant les engins et moyens de la Brigade","Les règles de vie en caserne","Les procédures radio en panne"]},{"id":"s:bsp:26","g":"bsp","k":"qcm","q":"Que signifie VSAV ?","answer":1,"explication":"Le VSAV traite le secours à victimes et assure leur transport vers l'hôpital. C'est l'engin que tu croiseras le plus souvent.","ref":{"d":"b30016","p":137},"choices":["Véhicule spécial d'appui ventilation","Véhicule de secours et d'assistance aux victimes","Voiture de soutien aux agents volontaires"]},{"id":"s:bsp:27","g":"bsp","k":"qcm","q":"Que signifie FPT ?","answer":2,"explication":"Le FPT est un engin-pompe puissant ; associé à un MEA et un second engin-pompe, il peut composer un départ normal.","ref":{"d":"b30016","p":19},"choices":["Fourgon de protection technique","Fourgon pour tuyaux","Fourgon pompe tonne"]},{"id":"s:bsp:28","g":"bsp","k":"qcm","q":"Dans le catalogue des moyens BSPP, PSE signifie…","answer":0,"explication":"Engin premier départ polyvalent, avec pompe et cellule sanitaire pour transporter les victimes. À ne pas confondre avec le PSE du secourisme (premiers secours en équipe) !","ref":{"d":"b30016","p":25},"choices":["Premier-secours évacuation","Poste de secours éloigné","Pompe de secours électrique"]},{"id":"s:bsp:29","g":"bsp","k":"qcm","q":"Que signifie EPSA ?","answer":2,"explication":"L'EPSA est une échelle aérienne (MEA) : sauvetages en étage, point haut d'observation. Associée à 2 EP, elle compose un DN.","ref":{"d":"b30016","p":43},"choices":["Engin pompe de secours aérien","Équipe de premiers secours avancés","Échelle pivotante semi-automatique"]},{"id":"s:bsp:30","g":"bsp","k":"vf","q":"Le VLR OGC est le véhicule qui transporte le colonel de garde.","answer":false,"explication":"Faux : il transporte l'officier de garde compagnie (OGC) et permet de monter un poste de commandement tactique de niveau 1.","ref":{"d":"b30016","p":55}},{"id":"s:bsp:31","g":"bsp","k":"qcm","q":"À qui s'adresse le BSP 200.20 ?","answer":1,"explication":"Il rassemble les EPI, matériels et savoir-faire NRBC à l'usage des sapeurs-pompiers primo-intervenants, les premiers arrivés sur les lieux.","ref":{"d":"b20020","p":1},"choices":["Aux opérateurs radio du CO","Aux sapeurs-pompiers primo-intervenants face au risque NRBC","Aux seuls plongeurs"]},{"id":"s:bsp:32","g":"bsp","k":"qcm","q":"Que signifie NRBC ?","answer":0,"explication":"Quatre familles de risques : nucléaire, radiologique, biologique et chimique.","ref":{"d":"b20020","p":84},"choices":["Nucléaire, radiologique, biologique, chimique","Naturel, routier, bâtimentaire, chimique","Nouveau risque bactériologique courant"]},{"id":"s:bsp:33","g":"bsp","k":"vf","q":"L'APRF (masque filtrant) est l'appareil à porter en espace confiné.","answer":false,"explication":"Faux : l'APRF s'utilise à l'air libre ; en espace confiné, c'est l'ARI qu'il faut porter.","ref":{"d":"b20020","p":9}},{"id":"s:bsp:34","g":"bsp","k":"qcm","q":"Combien de maillons compte la chaîne de survie NRBC (DUST-DAHO) ?","answer":1,"explication":"5 maillons, que les sapeurs-pompiers non spécialistes peuvent mener face à toute menace NRBC, quel que soit l'agent.","ref":{"d":"b20020","p":53},"choices":["3","5","10"]},{"id":"s:bsp:35","g":"bsp","k":"qcm","q":"Dans le guide PSE, que signifie DAE ?","answer":2,"explication":"Le DAE analyse le rythme cardiaque et guide le secouriste par messages sonores. Il ne remplace pas le massage, il le complète.","ref":{"d":"pse","p":528},"choices":["Dispositif d'alerte d'urgence","Dossier d'admission aux urgences","Défibrillateur automatisé externe"]},{"id":"s:bsp:36","g":"bsp","k":"qcm","q":"Arrêt cardiaque, à 2 secouristes avec matériel : quel rythme de RCP ?","answer":1,"explication":"30 compressions thoraciques puis 2 insufflations, et ainsi de suite, en mettant en œuvre le DAE au plus vite.","ref":{"d":"pse","p":124},"choices":["15 compressions pour 1 insufflation","30 compressions pour 2 insufflations","5 compressions pour 5 insufflations"]},{"id":"s:bsp:37","g":"bsp","k":"qcm","q":"Victime inconsciente qui respire normalement, sans traumatisme : tu la places…","answer":0,"explication":"La PLS maintient les voies aériennes libres. Ensuite, on protège du froid et on surveille la respiration.","ref":{"d":"pse","p":120},"choices":["En position latérale de sécurité (PLS)","Assise contre un mur","Debout pour la réveiller"]},{"id":"s:bsp:38","g":"bsp","k":"vf","q":"Adulte conscient qui s'étouffe complètement : on commence par 1 à 5 claques vigoureuses dans le dos.","answer":true,"explication":"Vrai : les claques dans le dos suffisent souvent. Si elles échouent, on passe aux compressions abdominales.","ref":{"d":"pse","p":109}},{"id":"s:bsp:39","g":"bsp","k":"vf","q":"Pendant la pose des électrodes du DAE, on arrête le massage cardiaque.","answer":false,"explication":"Faux : compressions et insufflations sont poursuivies pendant la mise en place du DAE ; on limite les interruptions au minimum.","ref":{"d":"pse","p":125}}],"docq":[{"q":"Tu prépares ta première garde au CS et veux savoir comment se passe la prise de garde.","d":"guide","p":5},{"q":"Tu cherches la liste des codes CRI à donner dans le message de rentrée.","d":"guide","p":51},{"q":"Tu veux connaître la composition des groupes de renfort (G.VEN, etc.).","d":"groupes","p":1},{"q":"Tu veux comprendre comment la BSPP décide quels engins envoyer sur une intervention.","d":"b1151","p":1},{"q":"Tu veux savoir comment le commandant des opérations de secours conduit une intervention.","d":"b1152","p":1},{"q":"La radio ou l'informatique tombe en panne : tu cherches les procédures de secours prévues.","d":"b1153","p":1},{"q":"Tu veux comprendre l'organisation générale de la BSPP (groupements, compagnies, centres de secours).","d":"b118","p":1},{"q":"Tu te demandes quelles sont les règles de vie à l'intérieur d'une caserne.","d":"b112","p":1},{"q":"Tu croises un engin inconnu et veux savoir à quoi il sert.","d":"b30016","p":1},{"q":"Tu veux connaître les équipements de protection face à un risque chimique ou radiologique.","d":"b20020","p":1},{"q":"Tu cherches la référence complète des secours et soins d'urgence pratiqués par les sapeurs-pompiers.","d":"b2002","p":1},{"q":"Tu veux revoir l'ordre du bilan primaire.","d":"bilan","p":1},{"q":"Tu veux revoir la prise en charge d'un arrêt cardiaque selon la BSPP.","d":"acr72","p":1},{"q":"Une victime est atteinte d'une maladie du sang qui provoque des crises douloureuses.","d":"drepano","p":1},{"q":"Tu te demandes qui est considéré comme une « victime » pour la BSPP.","d":"victime","p":1},{"q":"Tu dois reconnaître les signes d'un décès certain.","d":"deces","p":1},{"q":"Tu arrives à l'adresse mais personne n'ouvre et personne ne répond.","d":"noncontact","p":1},{"q":"Tu veux connaître les nouveautés 2025 du BSP 200.2.","d":"maj2025","p":1},{"q":"Tu veux connaître les évolutions réglementaires SSUAP de 2024.","d":"maj2024","p":1},{"q":"Une ambulance privée prend en charge ta victime : comment lui transmettre le bilan ?","d":"ambu","p":1},{"q":"Ta victime porte un gilet défibrillateur.","d":"lifevest","p":1},{"q":"La victime est accompagnée d'un chien guide d'aveugle.","d":"chiens","p":1},{"q":"Tu veux revoir les nouveautés de formation en traumatologie.","d":"trauma","p":1},{"q":"Tu veux revoir les nouveautés de formation sur l'arrêt cardiorespiratoire.","d":"macaacr","p":1},{"q":"Une personne âgée est tombée : tu veux revoir le relevage en gériatrie.","d":"chutes","p":1},{"q":"Un accouchement inopiné : tu veux revoir la réanimation du nouveau-né.","d":"nnn","p":1},{"q":"Tu veux revoir la fiche technique de mise en œuvre du défibrillateur.","d":"ft231","p":1},{"q":"Tu utilises le défibrillateur d'une pharmacie ou d'un lieu public.","d":"daecivil","p":1},{"q":"Canicule : tu veux savoir comment la BSPP adapte sa réponse aux coups de chaleur.","d":"chaleur2","p":1},{"q":"Tu cherches le manuel complet de la tablette de bilan électronique.","d":"efibi","p":1},{"q":"Tu veux une fiche récapitulative des conduites à tenir avec eFiBi.","d":"recap","p":1},{"q":"Tu veux signaler une situation sociale préoccupante depuis la tablette.","d":"ircs","p":1},{"q":"Les applications informatiques de la BSPP sont toutes indisponibles (mode dégradé 5).","d":"md5","p":1},{"q":"La victime est en arrêt cardiaque dès ton arrivée : comment le saisir sur la tablette ?","d":"tutoarr","p":1},{"q":"Ta tablette eFiBi bugue et tu dois effacer complètement ses données.","d":"suppr","p":1},{"q":"Tu te demandes quand demander la police sur intervention.","d":"police","p":1},{"q":"L'intervention a lieu dans une ambassade ou un consulat.","d":"ambassade","p":1},{"q":"Les pompiers sont entrés chez quelqu'un en son absence : que laisser sur place ?","d":"papillon","p":1},{"q":"Tu veux comprendre comment est traité un signalement social à Paris.","d":"vie","p":1},{"q":"Tu prends en main la nouvelle radio portative.","d":"tph","p":1},{"q":"Tu veux savoir quand faire appel au groupe d'intervention en milieu périlleux.","d":"grimp","p":1},{"q":"Tu veux réviser tes gestes de secouriste Croix-Rouge (PSE).","d":"pse","p":1}],"fam":{"b2002":"ssuap","bilan":"ssuap","acr72":"ssuap","drepano":"ssuap","victime":"ssuap","deces":"ssuap","noncontact":"ssuap","noncontact2":"ssuap","maj2025":"ssuap","maj2024":"ssuap","ambu":"ssuap","reveil":"ssuap","lifevest":"ssuap","chiens":"ssuap","trauma":"ssuap","macaacr":"ssuap","chutes":"ssuap","nnn":"ssuap","ft231":"ssuap","daecivil":"ssuap","chaleur":"ssuap","chaleur2":"ssuap","dsa":"ssuap","macaintro":"ssuap","efibi":"efibi","recap":"efibi","ircs":"efibi","md5":"efibi","tutoarr":"efibi","tutobil":"efibi","suppr":"efibi","macaefibi":"efibi","vie":"efibi","mcori":"efibi","b1151":"regl","b1152":"regl","b1153":"regl","b118":"regl","b112":"regl","b30016":"regl","b20020":"regl","groupes":"regl","police":"regl","ambassade":"regl","papillon":"regl","tph":"regl","grimp":"regl","guide":"guide","pse":"pse"}};